insert into questions (id, unit, topic, concept, stem, choices, answer, why) values
  ('Q01', 'Quantitative Methods', 'Time Value of Money', 'Annuity due timing', 'An annuity due differs from an ordinary annuity in that its payments occur:', '["At the end of each period","Only at the midpoint of each period","At the beginning of each period"]'::jsonb, 2, 'An annuity due places each cash flow at the start of the period, one period earlier than an ordinary annuity, so both its present value and future value equal the ordinary annuity value multiplied by (1 + r). End-of-period timing is the ordinary-annuity default that most financial calculators assume unless BGN mode is set, which is why it is the tempting first guess.'),
  ('Q02', 'Quantitative Methods', 'Time Value of Money', 'FV lump sum', 'An investor deposits $8,000 in an account that earns 6% compounded annually. The value of the account after 5 years is closest to:', '["$10,706","$10,400","$10,100"]'::jsonb, 0, 'Compounding for 5 years gives 8,000 × 1.06^5 = $10,706. The $10,400 figure comes from simple interest (8,000 × 1.30), ignoring that interest itself earns interest, and $10,100 stops the compounding one year early at 1.06^4.'),
  ('Q03', 'Quantitative Methods', 'Time Value of Money', 'PV ordinary annuity', 'What is the present value of an ordinary annuity that pays $2,500 at the end of each year for 6 years, given a 7% discount rate?', '["$12,750","$17,883","$11,916"]'::jsonb, 2, 'Discounting six $2,500 payments at 7% gives a present value of $11,916. The $12,750 figure is the annuity-due version of the same cash flows, shifted a year earlier, and $17,883 is the future, not present, value of the same annuity -- a classic calculator-key mix-up.'),
  ('Q04', 'Quantitative Methods', 'Time Value of Money', 'FV annuity due', 'A saver contributes $4,000 at the beginning of each year to an account earning 5% annually for 10 years. The value of the account at the end of year 10 is closest to:', '["$50,312","$52,827","$46,312"]'::jsonb, 1, 'Because each deposit is made at the start of the year, this is an annuity due, so the ordinary-annuity future value of $50,312 must be bumped up by one more year of growth, giving $52,827. The $46,312 figure comes from miscounting only nine beginning-of-year deposits instead of ten.'),
  ('Q05', 'Quantitative Methods', 'Time Value of Money', 'Stated vs effective rate', 'A bank quotes a stated annual rate of 8%, compounded monthly. Compared with the stated rate, the effective annual rate is:', '["Higher, because interest earned within the year itself earns interest","Lower, because monthly compounding reduces the annual cost","Equal, because compounding frequency does not affect the annual rate"]'::jsonb, 0, 'Compounding more often than once a year lets interest earned mid-year start earning interest of its own before year-end, so the effective annual rate always exceeds the stated rate whenever compounding happens more than annually. The equal-rate choice is true only for annual compounding; no compounding frequency ever pushes the effective rate below the stated rate.'),
  ('Q06', 'Quantitative Methods', 'Time Value of Money', 'EAR calculation', 'A stated annual rate of 12% is compounded semiannually. The effective annual rate is closest to:', '["12.36%","12.00%","12.68%"]'::jsonb, 0, 'EAR = (1 + 0.12/2)^2 - 1 = 1.06^2 - 1 = 12.36%. The 12.00% figure is just the stated rate with no compounding applied at all, and 12.68% comes from compounding monthly instead of semiannually -- using the wrong number of compounding periods for the rate actually quoted.'),
  ('Q07', 'Quantitative Methods', 'Time Value of Money', 'Uneven cash flow PV', 'A project is expected to generate cash flows of $3,000 at the end of year 1, $5,000 at the end of year 2, and $7,000 at the end of year 3. At a 9% discount rate, the present value of these cash flows is closest to:', '["$15,000","$12,366","$13,761"]'::jsonb, 1, 'Each cash flow must be discounted for its own number of years: 3,000/1.09 + 5,000/1.09^2 + 7,000/1.09^3 = $12,366. The $15,000 figure simply adds the undiscounted cash flows, and $13,761 discounts their sum once at 1.09^1 -- treating an uneven series as if all the cash arrived in year 1.'),
  ('Q08', 'Quantitative Methods', 'Time Value of Money', 'Solving for PMT', 'A parent wants to accumulate $100,000 in 10 years for a child''s education. The account currently holds $20,000, and both the existing balance and future deposits earn 6% annually. If the parent makes one deposit at the end of each year for 10 years, the required annual deposit is closest to:', '["$7,587","$4,869","$6,069"]'::jsonb, 1, 'The existing $20,000 grows to 20,000 × 1.06^10 = $35,817 on its own, leaving only $64,183 for the deposits to cover, so the required payment is $4,869. The $7,587 figure ignores the existing balance entirely, and $6,069 nets it out at its current $20,000 value without first growing it for 10 years -- both forget that money already saved keeps compounding too.'),
  ('Q09', 'Quantitative Methods', 'Descriptive Statistics', 'Sample vs population variance', 'When computing the variance of a sample rather than the population, the sum of squared deviations from the mean is divided by:', '["n - 1, to correct for the bias of using the sample mean","n, the sample size","n + 1, to widen the estimate"]'::jsonb, 0, 'Sample variance divides by n - 1 (Bessel''s correction) because using the sample mean instead of the true population mean makes the raw sum of squared deviations systematically too small. Dividing by n alone reproduces that downward bias and is correct only for population variance, where the true mean is already known rather than estimated.'),
  ('Q10', 'Quantitative Methods', 'Descriptive Statistics', 'Sample standard deviation', 'A sample of five portfolio returns is: 4%, 6%, 8%, 10%, 12%. The sample standard deviation is closest to:', '["2.83%","3.16%","10.00%"]'::jsonb, 1, 'The mean is 8%, the squared deviations sum to 40, and dividing by n - 1 = 4 gives a sample variance of 10, so the sample standard deviation is the square root of 10, or 3.16%. Dividing by n = 5 instead gives the 2.83% population figure, and 10.00% is the variance itself reported without taking the square root.'),
  ('Q11', 'Quantitative Methods', 'Descriptive Statistics', 'Median calculation', 'A small hedge fund reports monthly returns for six months: 2%, 3%, 3%, 4%, 5%, and -25% (one month of steep losses). The median monthly return is:', '["-1.33%","3.50%","3.00%"]'::jsonb, 2, 'Sorting the six returns gives -25%, 2%, 3%, 3%, 4%, 5%, so the median is the average of the two middle values, 3% and 3%, which is 3.00%. Averaging the third and fourth values in their original, unsorted order (3% and 4%) gives the tempting but wrong 3.50%, and -1.33% is the mean, which the large loss drags well below the median.'),
  ('Q12', 'Quantitative Methods', 'Descriptive Statistics', 'Positive skewness', 'A distribution of returns has a long right tail with most observations clustered at lower values. Relative to the median, the mean of this distribution is most likely:', '["Less than the median, because extreme low values pull it down","Equal to the median, because skewness does not affect the mean","Greater than the median, because extreme high values pull it up"]'::jsonb, 2, 'A long right tail is positive skew, and the few extreme high observations pull the mean above the median -- the textbook mean-greater-than-median signature of a right-skewed distribution. The equal-to-the-median choice describes only a symmetric distribution, where skewness is zero and mean, median, and mode all coincide.'),
  ('Q13', 'Quantitative Methods', 'Descriptive Statistics', 'Weighted mean', 'A portfolio holds three assets: 50% in Asset A (return 10%), 30% in Asset B (return 4%), and 20% in Asset C (return -6%). The portfolio''s weighted mean return is:', '["2.67%","5.00%","0.20%"]'::jsonb, 1, 'Weighting each return by its portfolio share gives 0.50(10%) + 0.30(4%) + 0.20(-6%) = 5.00%. The 2.67% figure is the plain, unweighted average of the three returns, and 0.20% comes from applying the weights in the wrong order (20%/30%/50% instead of 50%/30%/20%) to the same three returns.'),
  ('Q14', 'Quantitative Methods', 'Descriptive Statistics', 'Excess kurtosis', 'A return distribution has an excess kurtosis of 2.5. Relative to the normal distribution, this distribution is:', '["Platykurtic, with thinner tails and less peaked than normal","Leptokurtic, with fatter tails and a higher peak than normal","Mesokurtic, identical in shape to the normal distribution"]'::jsonb, 1, 'Excess kurtosis is measured relative to the normal distribution''s kurtosis of 3, so a positive excess kurtosis of 2.5 (a raw kurtosis of 5.5) means fatter tails and a higher peak -- leptokurtic. Platykurtic describes a negative excess kurtosis, thinner tails and a flatter peak than normal, the opposite of what a positive figure indicates.'),
  ('Q15', 'Quantitative Methods', 'Descriptive Statistics', 'Geometric mean return', 'An investment returns 20% in year 1 and -10% in year 2. The geometric mean annual return over the two years is closest to:', '["5.00%","3.92%","8.00%"]'::jsonb, 1, 'The geometric mean compounds the two growth factors and takes the square root: sqrt(1.20 × 0.90) - 1 = sqrt(1.08) - 1 = 3.92%. The 5.00% figure is the arithmetic mean, which overstates compound growth whenever returns vary, and 8.00% multiplies the two growth factors correctly but forgets to take the square root, leaving a two-year cumulative return dressed up as an annual one.'),
  ('Q16', 'Quantitative Methods', 'Probability Concepts', 'Mutual exclusivity vs independence', 'Two events A and B each have positive probability. If A and B are mutually exclusive, then A and B are:', '["Necessarily dependent, since the occurrence of one rules out the other","Also independent, since neither event constrains the other","Independent only if P(A) = P(B)"]'::jsonb, 0, 'Mutually exclusive events cannot both occur, so knowing A happened tells you B did not -- P(B|A) = 0, which is not equal to P(B) -- and that is precisely the definition of dependence. Two events with positive individual probabilities can never be both mutually exclusive and independent, which makes the also-independent choice the single most common probability mix-up on the exam, since the two terms sound similar but describe nearly opposite conditions.'),
  ('Q17', 'Quantitative Methods', 'Probability Concepts', 'Independent joint probability', 'The probability that a randomly selected candidate passes the Level I exam is 0.45. The probability that a randomly selected candidate has a finance degree is 0.30, independent of passing. The probability that a randomly selected candidate both has a finance degree and passes is:', '["13.5%","75.0%","45.0%"]'::jsonb, 0, 'For independent events, the joint probability is the product of the marginals: 0.45 × 0.30 = 13.5%. The 75.0% figure comes from adding the two probabilities instead of multiplying them, and 45.0% just restates the pass probability alone, mistaking the fact that independence keeps a conditional probability unchanged for a claim about the joint probability itself.'),
  ('Q18', 'Quantitative Methods', 'Probability Concepts', 'Expected value', 'A stock will return 25% with probability 0.20, 10% with probability 0.50, and -15% with probability 0.30. The expected return is:', '["6.67%","14.5%","5.5%"]'::jsonb, 2, 'Expected return weights each outcome by its probability: 0.20(25%) + 0.50(10%) + 0.30(-15%) = 5.5%. The 6.67% figure is the plain average of the three outcomes with the probabilities ignored, and 14.5% drops the negative sign on the loss scenario, treating a -15% outcome as a +15% gain.'),
  ('Q19', 'Quantitative Methods', 'Probability Concepts', 'Covariance from correlation', 'The correlation between the returns of Stock X and Stock Y is 0.40. The standard deviation of X''s returns is 20% and of Y''s returns is 15%. The covariance between the two return series is closest to:', '["0.0120","0.0300","0.0048"]'::jsonb, 0, 'Covariance equals correlation times both standard deviations: 0.40 × 0.20 × 0.15 = 0.0120. The 0.0300 figure is just the product of the two standard deviations with the correlation ignored, as if the two return series moved in perfect lockstep, and 0.0048 comes from squaring the correlation coefficient first -- confusing correlation with R-squared, a closely related but distinct statistic.'),
  ('Q20', 'Quantitative Methods', 'Probability Concepts', 'Bayes'' formula concept', 'An analyst wants to update the probability that a company will beat earnings estimates after observing that its CFO sold shares last week. This is an application of:', '["The total probability rule, which decomposes an unconditional probability into weighted conditional pieces","Bayes'' formula, which revises a prior probability using new information to form a posterior probability","The multiplication rule for independent events, since the two events are unrelated"]'::jsonb, 1, 'Bayes'' formula takes a prior probability (beating estimates) and revises it in light of new evidence (the CFO''s share sale) to produce a posterior probability -- exactly this prior-to-posterior updating sequence. The total probability rule runs in the opposite direction, building an unconditional probability up from scenario-conditional pieces rather than revising a belief given new information.'),
  ('Q21', 'Quantitative Methods', 'Probability Concepts', 'Correlation bounds', 'The correlation coefficient between two variables can take on:', '["Any real number, positive or negative, without bound","Only values between -1 and +1, inclusive","Only values between 0 and 1, inclusive"]'::jsonb, 1, 'Correlation is a standardized measure of linear association and is bounded between -1 and +1 by construction, with the extremes representing perfect negative and perfect positive linear relationships. The 0-to-1 range actually describes R-squared, the coefficient of determination, not correlation itself -- a frequent mix-up between the two related statistics.'),
  ('Q22', 'Quantitative Methods', 'Probability Concepts', 'Total probability rule', 'A bond defaults with probability 0.08 if the economy is in recession and 0.01 if the economy is not in recession. The probability of a recession next year is 0.25. Using the total probability rule, the unconditional probability of default is:', '["4.50%","3.00%","2.75%"]'::jsonb, 2, 'The total probability rule weights each conditional default probability by its scenario''s likelihood: 0.25(0.08) + 0.75(0.01) = 2.75%. The 4.50% figure is a plain, unweighted average of the two conditional probabilities, and 3.00% weights the recession branch correctly but forgets to weight the no-recession branch by its 0.75 probability at all.'),
  ('Q23', 'Quantitative Methods', 'Probability Concepts', 'Bayes'' formula calculation', 'In a given market, 30% of analysts are ''skilled'' and 70% are ''unskilled.'' A skilled analyst outperforms the benchmark in any given year with probability 0.70; an unskilled analyst does so with probability 0.40. An analyst is randomly selected and observed to outperform the benchmark this year. The probability that this analyst is skilled is closest to:', '["70.0%","42.9%","30.0%"]'::jsonb, 1, 'By Bayes'' formula, P(outperform) = 0.30(0.70) + 0.70(0.40) = 0.49, so P(skilled | outperform) = 0.30(0.70) / 0.49 = 42.9%. The 70.0% figure reports P(outperform | skilled) instead -- the single most common Bayes error, transposing the conditional -- and 30.0% is just the unrevised prior, as if the outperformance evidence were never observed at all.'),
  ('Q24', 'Quantitative Methods', 'Common Probability Distributions', 'Normal distribution properties', 'Which statement about the normal distribution is correct?', '["It is completely described by its mean and variance, and is symmetric with skewness of zero","It is bounded between 0 and 1 and is used to model stock prices directly","It has fatter tails than the Student''s t-distribution with any finite degrees of freedom"]'::jsonb, 0, 'The normal distribution is fully specified by just two parameters, its mean and variance, and is symmetric around the mean with zero skewness. Stock prices are typically modeled as lognormal rather than normal precisely because a normal variable can go negative, and the normal distribution actually has thinner tails than any Student''s t-distribution, which is why the t is used instead whenever sample size is small.'),
  ('Q25', 'Quantitative Methods', 'Common Probability Distributions', 'Student''s t vs z', 'An analyst is estimating a confidence interval for a population mean using a sample of 15 observations drawn from a normally distributed population with unknown population variance. The appropriate distribution to use is:', '["The Student''s t-distribution, because the population variance is unknown and the sample is small","The standard normal (z) distribution, because the sample is drawn from a normal population","The binomial distribution, because the outcome is a sample mean"]'::jsonb, 0, 'With the population variance unknown, the sample standard deviation must be substituted in, and that added estimation uncertainty is exactly what the Student''s t-distribution accounts for, especially in a small sample. Using z here ignores that the population standard deviation is being estimated rather than known, understating how uncertain the interval really is; the t-distribution converges to z only as the sample grows large.'),
  ('Q26', 'Quantitative Methods', 'Common Probability Distributions', 'Lognormal distribution use', 'A key reason analysts use the lognormal distribution rather than the normal distribution to model asset prices is that the lognormal distribution:', '["Is bounded at zero, so it cannot produce a negative asset price","Is symmetric, matching the symmetric behavior of price changes","Has a mean that always equals its median"]'::jsonb, 0, 'Asset prices cannot fall below zero, and the lognormal distribution is bounded below at zero, unlike the normal distribution, which allows any negative value. The lognormal distribution is also right-skewed rather than symmetric, and its mean exceeds its median precisely because of that skew -- the opposite of what the equal-mean-and-median choice claims.'),
  ('Q27', 'Quantitative Methods', 'Common Probability Distributions', 'Binomial probability', 'A portfolio manager has historically beaten the benchmark in 60% of quarters, independent quarter to quarter. Using the binomial distribution, the probability that the manager beats the benchmark in exactly 2 of the next 3 quarters is closest to:', '["14.4%","21.6%","43.2%"]'::jsonb, 2, 'The binomial probability of exactly 2 successes in 3 trials is C(3,2) × 0.6^2 × 0.4^1 = 3 × 0.36 × 0.4 = 43.2%. The 14.4% figure drops the combinatorial count of 3 ways to arrange 2 successes among 3 quarters, and 21.6% is the probability of beating the benchmark all three quarters (0.6^3), answering exactly-3 instead of exactly-2.'),
  ('Q28', 'Quantitative Methods', 'Common Probability Distributions', 'Continuous uniform distribution', 'A stock''s daily price change is uniformly distributed between -$2 and $3. The probability that the price change is between $0 and $1 is:', '["20.0%","33.3%","60.0%"]'::jsonb, 0, 'The full range of the distribution is $5 (from -2 to 3), and the interval from 0 to 1 has width $1, so the probability is 1/5 = 20.0%. The 33.3% figure treats 3 (the distance from 0 to the upper bound) as the relevant total range instead of the true width of 5, and 60.0% computes the probability of a change at or below $1 (a width of 3 out of 5) rather than the probability of landing specifically between 0 and 1.'),
  ('Q29', 'Quantitative Methods', 'Common Probability Distributions', 'Normal distribution range', 'A fund''s annual returns are normally distributed with a mean of 9% and a standard deviation of 4%. Using the fact that approximately 95% of a normal distribution lies within 1.96 standard deviations of the mean, the range that captures approximately 95% of expected annual returns is closest to:', '["(5.00%, 13.00%)","(1.16%, 16.84%)","(7.04%, 10.96%)"]'::jsonb, 1, 'The 95% range is the mean plus or minus 1.96 standard deviations: 9% +/- 1.96(4%) = 9% +/- 7.84%, or (1.16%, 16.84%). The (5.00%, 13.00%) range instead uses 1 standard deviation, the multiplier for the roughly 68% band, not 95%, and (7.04%, 10.96%) adds and subtracts 1.96 directly without ever scaling it by the 4% standard deviation.'),
  ('Q30', 'Quantitative Methods', 'Common Probability Distributions', 'Binomial cumulative probability', 'A bond avoids default in any given year with probability 0.95, independent across years. Using the binomial distribution, the probability that the bond avoids default in at least 2 of the next 3 years is closest to:', '["85.7%","13.5%","99.3%"]'::jsonb, 2, 'At least 2 of 3 means exactly 2 or exactly 3: C(3,2)(0.95^2)(0.05) + 0.95^3 = 13.5% + 85.7% = 99.3%. The 85.7% figure only captures the exactly-3 case and stops there, and 13.5% only captures the exactly-2 case -- both forget that ''at least'' requires summing every qualifying outcome, not picking just one of them.'),
  ('Q31', 'Quantitative Methods', 'Sampling and Estimation', 'Central limit theorem', 'According to the central limit theorem, as sample size n increases, the sampling distribution of the sample mean:', '["Approaches a normal distribution regardless of the shape of the underlying population distribution","Approaches the shape of the underlying population distribution, whatever that shape is","Becomes uniform, since sampling error is equally likely in any direction"]'::jsonb, 0, 'The central limit theorem guarantees that the sampling distribution of the sample mean approaches normality as n grows large (n >= 30 is a common rule of thumb), even when the underlying population is skewed or otherwise non-normal. Claiming the sampling distribution simply mirrors the population''s own shape describes what actually happens only with a small sample -- exactly the problem the central limit theorem solves as n increases.'),
  ('Q32', 'Quantitative Methods', 'Sampling and Estimation', 'Standard error definition', 'The standard error of the sample mean is best described as:', '["The standard deviation of the sampling distribution of the sample mean","The standard deviation of the individual observations in the sample","The square root of the sample size"]'::jsonb, 0, 'The standard error measures how much the sample mean itself would vary from sample to sample, equal to the standard deviation divided by the square root of n -- smaller than, and conceptually distinct from, the standard deviation of individual observations. Confusing the two is common because both get called a standard deviation of something, but only one describes how precisely the mean estimates the true population value.'),
  ('Q33', 'Quantitative Methods', 'Sampling and Estimation', 'Sample size effect on CI', 'Holding the confidence level and population standard deviation constant, quadrupling the sample size will cause the width of a confidence interval for the mean to:', '["Fall to a quarter of its original width, in direct proportion to sample size","Stay the same, because the confidence level was not changed","Fall by half, because the standard error shrinks with the square root of sample size"]'::jsonb, 2, 'Standard error equals sigma over the square root of n, so quadrupling n doubles the square root of n, cutting the standard error -- and the confidence interval''s width -- in half. Expecting the width to fall to a quarter assumes it scales directly with sample size rather than with the square root of sample size, overstating how much precision a larger sample actually buys.'),
  ('Q34', 'Quantitative Methods', 'Sampling and Estimation', 'Standard error calculation', 'A sample of 100 observations is drawn from a population with a standard deviation of 25. The standard error of the sample mean is:', '["0.25","2.5","25.0"]'::jsonb, 1, 'Standard error equals the standard deviation divided by the square root of the sample size: 25 / sqrt(100) = 25/10 = 2.5. The 0.25 figure divides by n instead of the square root of n, and 25.0 simply reports the population standard deviation itself, as if individual-observation variability and the precision of the sample mean were the same thing.'),
  ('Q35', 'Quantitative Methods', 'Sampling and Estimation', 'Confidence interval for mean', 'A random sample of 64 bond yields has a mean of 5.2% and a population standard deviation of 1.6%. A 95% confidence interval for the population mean, using a critical z-value of 1.96, is closest to:', '["(5.15%, 5.25%)","(2.06%, 8.34%)","(4.81%, 5.59%)"]'::jsonb, 2, 'The standard error is 1.6%/sqrt(64) = 0.20%, so the margin of error is 1.96 × 0.20% = 0.392%, giving an interval of 5.2% +/- 0.392%, or (4.81%, 5.59%). The (5.15%, 5.25%) interval divides by n instead of the square root of n, making the interval implausibly tight, while (2.06%, 8.34%) applies the z-value directly to the 1.6% population standard deviation, skipping the standard-error step entirely and making the interval far too wide.'),
  ('Q36', 'Quantitative Methods', 'Sampling and Estimation', 'Margin of error', 'A sample of 36 observations has a standard deviation of 12. The margin of error for a 95% confidence interval, using a critical z-value of 1.96, is closest to:', '["3.92","0.65","3.29"]'::jsonb, 0, 'The standard error is 12/sqrt(36) = 2, so the margin of error is 1.96 × 2 = 3.92. The 0.65 figure divides by n instead of the square root of n before applying the z-value, and 3.29 applies the correct standard error of 2 but multiplies it by 1.645, the critical value for a 90% confidence level, not the 95% level this question asks for.'),
  ('Q37', 'Quantitative Methods', 'Sampling and Estimation', 'Sample size determination', 'A researcher wants a margin of error no greater than 2 for a 95% confidence interval, using a critical z-value of 1.96 and an assumed population standard deviation of 15. The minimum sample size required is closest to:', '["14.7","216","152"]'::jsonb, 1, 'Solving the margin-of-error formula for n gives n = (z × sigma / E)^2 = (1.96 × 15 / 2)^2 = 14.7^2 = 216. The 14.7 figure stops one step early, forgetting that the formula must be squared to solve for n rather than for the margin itself, and 152 performs that same squaring step correctly but with the 90% critical value of 1.645 substituted for the 95% value the question specifies.'),
  ('Q38', 'Quantitative Methods', 'Hypothesis Testing', 'Type I error', 'A Type I error in hypothesis testing occurs when:', '["The null hypothesis is true but is rejected","The null hypothesis is false but fails to be rejected","The alternative hypothesis is true and is correctly accepted"]'::jsonb, 0, 'A Type I error is a false rejection of a true null hypothesis, and its probability is the significance level, alpha, chosen before the test is run. Describing a false failure to reject a false null is the definition of a Type II error instead, and the two are easy to swap since both simply describe the test getting it wrong.'),
  ('Q39', 'Quantitative Methods', 'Hypothesis Testing', 'Type I vs II tradeoff', 'Holding the sample size constant, decreasing the significance level (alpha) of a hypothesis test from 5% to 1% will:', '["Decrease the probability of a Type I error and decrease the probability of a Type II error","Have no effect on the probability of a Type II error, since the two error types are independent","Decrease the probability of a Type I error and increase the probability of a Type II error"]'::jsonb, 2, 'A stricter significance level directly lowers the chance of a Type I error, but for a fixed sample size that same stricter rejection criterion makes it harder to reject the null even when it is false, raising the Type II error rate -- the two trade off against each other. Assuming both errors fall together ignores that they are governed by the same critical value, so tightening one loosens the other unless the sample size also changes.'),
  ('Q40', 'Quantitative Methods', 'Hypothesis Testing', 'One-tailed vs two-tailed', 'An analyst wants to test whether a fund''s mean return is different from a benchmark''s mean return of 8%, with no prior view on direction. The appropriate test is:', '["A one-tailed test, since only one specific value is being tested","Not able to be tested with a t-test or z-test, since there is no directional hypothesis","A two-tailed test, since the alternative hypothesis allows for deviation in either direction"]'::jsonb, 2, 'Because the analyst has no prior view on direction and only wants to know whether the mean differs from 8% at all, the alternative hypothesis is two-sided (not equal to 8%), which splits the rejection region across both tails. A one-tailed test is reserved for a directional claim, such as testing specifically whether the return is greater than, or specifically less than, the benchmark.'),
  ('Q41', 'Quantitative Methods', 'Hypothesis Testing', 't-test statistic', 'A sample of 25 monthly returns has a mean of 1.8% and a sample standard deviation of 2.5%. Testing the null hypothesis that the true mean return equals 1.0% against a two-sided alternative, the test statistic is closest to:', '["0.32","8.00","1.60"]'::jsonb, 2, 'The test statistic is the difference from the hypothesized mean divided by the standard error: (1.8% - 1.0%) / (2.5%/sqrt(25)) = 0.8/0.5 = 1.60. The 0.32 figure divides by the sample standard deviation directly instead of the standard error, and 8.00 divides by 2.5%/25 -- using n instead of the square root of n in the denominator.'),
  ('Q42', 'Quantitative Methods', 'Hypothesis Testing', 'z-test statistic', 'A sample of 100 observations has a mean of 52 and is drawn from a population with a known standard deviation of 15. Testing the null hypothesis that the population mean equals 50 against a two-sided alternative, the test statistic is closest to:', '["1.33","0.13","13.33"]'::jsonb, 0, 'With the population standard deviation known and a large sample, the z-test statistic is (52 - 50) / (15/sqrt(100)) = 2/1.5 = 1.33. The 0.13 figure divides by the standard deviation directly rather than the standard error, and 13.33 divides by 15/100 -- using n rather than the square root of n in the denominator, the same scaling error in the opposite direction.'),
  ('Q43', 'Quantitative Methods', 'Hypothesis Testing', 'p-value adjustment', 'A two-sided hypothesis test produces a p-value of 0.048. If the same sample data were instead used to test a one-sided alternative consistent with the direction of the observed test statistic, the one-sided p-value would be closest to:', '["0.048","0.024","0.096"]'::jsonb, 1, 'For a symmetric test statistic, splitting a two-sided p-value''s rejection region into a single tail halves it: 0.048/2 = 0.024. Reporting 0.048 unchanged forgets that a one-sided test concentrates the entire rejection region in one tail rather than splitting it across both, and 0.096 doubles the p-value instead of halving it, reversing the direction of the adjustment.'),
  ('Q44', 'Quantitative Methods', 'Hypothesis Testing', 'Full hypothesis test', 'A sample of 16 observations drawn from an approximately normal population has a mean of 45 and a sample standard deviation of 8. An analyst tests the null hypothesis that the population mean is 40 against a two-sided alternative, using a critical t-value of 2.131 at the 5% significance level. The correct conclusion is:', '["Fail to reject the null hypothesis, because a test statistic of 0.63 is below the 2.131 critical value","Reject the null hypothesis, because a test statistic of 10.00 far exceeds the 2.131 critical value","Reject the null hypothesis, because the test statistic of 2.50 exceeds the 2.131 critical value"]'::jsonb, 2, 'The test statistic is (45 - 40) / (8/sqrt(16)) = 5/2 = 2.50, which exceeds the two-tailed critical value of 2.131, so the null is rejected. A test statistic of 0.63 comes from dividing the 5-point difference by the sample standard deviation of 8 directly rather than by the standard error of 2, and a test statistic of 10.00 comes from dividing by 8/16 instead of 8/sqrt(16) -- both scale the denominator incorrectly rather than getting the direction of the decision wrong.'),
  ('Q45', 'Quantitative Methods', 'Simple Linear Regression', 'Slope coefficient interpretation', 'In the regression Return_i = 0.02 + 1.3 × MarketReturn_i + error, the slope coefficient of 1.3 is best interpreted as:', '["The predicted value of Return when MarketReturn equals zero","The expected change in Return for a one-unit change in MarketReturn","The proportion of variation in Return explained by MarketReturn"]'::jsonb, 1, 'The slope coefficient measures the expected change in the dependent variable for a one-unit increase in the independent variable: here, a one-unit increase in market return is associated with a 1.3-unit increase in the stock''s return. The predicted value when MarketReturn equals zero is the intercept, 0.02, not the slope, and the proportion of variation explained is R-squared, a different regression statistic entirely.'),
  ('Q46', 'Quantitative Methods', 'Simple Linear Regression', 'R-squared interpretation', 'A simple linear regression of a stock''s returns on the market''s returns produces an R-squared of 0.64. The most correct interpretation is that:', '["The correlation between the stock''s returns and the market''s returns is 0.64","64% of the variation in the stock''s returns is explained by variation in the market''s returns","64% of the stock''s individual return observations are correctly predicted by the model"]'::jsonb, 1, 'R-squared is the proportion of total variation in the dependent variable explained by the independent variable, so an R-squared of 0.64 means 64% of the variation in stock returns is explained by market returns. In a simple regression the correlation is the square root of R-squared, or 0.80 here, not 0.64 itself, and R-squared describes explained variance, not the share of individual observations a model gets exactly right.'),
  ('Q47', 'Quantitative Methods', 'Simple Linear Regression', 'Slope coefficient calculation', 'A simple linear regression of Y on X has a covariance between X and Y of 45 and a variance of X of 25. The estimated slope coefficient is:', '["0.56","9.00","1.80"]'::jsonb, 2, 'The slope coefficient equals the covariance between X and Y divided by the variance of X: 45/25 = 1.80. The 0.56 figure inverts the ratio (variance of X over covariance), and 9.00 divides the covariance by the standard deviation of X, 5, instead of the variance of X, 25.'),
  ('Q48', 'Quantitative Methods', 'Simple Linear Regression', 'Intercept calculation', 'A simple linear regression has an estimated slope coefficient of 0.8. The mean of the dependent variable is 12 and the mean of the independent variable is 10. The estimated intercept is:', '["20","2","4"]'::jsonb, 2, 'The intercept is the mean of Y minus the slope times the mean of X: 12 - 0.8(10) = 4. The value of 20 adds the slope''s contribution instead of subtracting it, and 2 subtracts the two means directly (12 - 10) without first scaling the mean of X by the slope coefficient.'),
  ('Q49', 'Quantitative Methods', 'Simple Linear Regression', 'Regression predicted value', 'A regression estimates Sales = 150 + 4.5 × Advertising, where Sales and Advertising are both measured in thousands of dollars. For Advertising of 40 (thousand dollars), predicted Sales is:', '["330","180","154.5"]'::jsonb, 0, 'Predicted Sales is the intercept plus the slope times the given value of Advertising: 150 + 4.5(40) = 330. The 180 figure applies only the slope term and drops the intercept entirely, and 154.5 adds the intercept and the raw slope coefficient (150 + 4.5) without ever multiplying the slope by the Advertising value of 40.'),
  ('Q50', 'Quantitative Methods', 'Simple Linear Regression', 'Slope significance test', 'A simple linear regression based on 32 observations produces a slope coefficient of 2.4 with a standard error of 0.8. Testing the null hypothesis that the true slope equals zero, using a critical t-value of 2.042 at the 5% significance level, the correct conclusion is:', '["Fail to reject the null hypothesis; a t-statistic of 3.00 does not exceed 2.042","Reject the null hypothesis; a t-statistic of 3.00 exceeds the 2.042 critical value, so the slope is statistically significant","Reject the null hypothesis, but only because the slope coefficient of 2.4 is a large number in absolute terms"]'::jsonb, 1, 'The t-statistic for a slope coefficient is the coefficient divided by its own standard error: 2.4/0.8 = 3.00, which exceeds the critical value of 2.042, so the null hypothesis that the true slope is zero is rejected. Claiming 3.00 does not exceed 2.042 simply gets the comparison backwards, and judging significance by the coefficient''s raw size ignores that significance depends on the coefficient relative to its standard error, not on the coefficient alone.');
